108	    #[test]
109	    fn accepts_the_forms_strtol_accepts() {
110	        for (input, expected) in [
111	            ("80", 80),
112	            ("080", 80),
113	            ("+80", 80),
114	            (" 80", 80),
115	            ("\t80", 80),
116	            ("80 ", 80),
117	            ("8 0", 8),
118	            ("80abc", 80),
119	            ("80.9", 80),
120	            ("0x50", 0),
121	            ("1e3", 1),
122	            ("-0", 0),
123	            ("  -42xyz", -42),
124	            ("-1", -1),
125	            ("2147483647", i32::MAX),
126	            ("-2147483648", i32::MIN),
127	        ] {
128	            assert_eq!(stoi(input), Ok(expected), "input {input:?}");
129	        }
130	    }
131	
