143	    #[test]
144	    fn rejects_values_outside_int_range() {
145	        for input in [
146	            "2147483648",
147	            "-2147483649",
148	            "99999999999999999999",
149	            "-99999999999999999999",
150	        ] {
151	            assert_eq!(stoi(input), Err(StoiError::OutOfRange), "input {input:?}");
152	        }
153	    }
154	}
